using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/ui-profile");
            if (!s.Load())
                throw new Exception("UI private save");
            s.OpenPage("conclusions");
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/conclusion-buttons-before.png");
            r.Log("Loaded existing UI-entered records; finalized=" + s.data.finalized);
        }
    }
}

